// Random per-window channel, explicit return, bounded payload and stale-source checks.
export function createFrameSender({token,frame,look,onLook,onError=()=>{},channelFactory=name=>new BroadcastChannel(name)}){
 if(!/^[a-f0-9-]{36}$/.test(token))throw Error('Invalid bridge token');const channel=channelFactory('artoftomworks.frame.'+token);let source=null,closed=false,failed=false;
 function send(){if(closed)return;if(failed)channel.postMessage({version:1,type:'failed',token});else if(source)channel.postMessage({version:1,type:'frame',token,frame:source,look:look||null});}
 channel.onmessage=e=>{const m=e.data;if(m?.version!==1||m.token!==token)return;if(m.type==='hello')send();else if(m.type==='look')try{onLook(m.recipe,Number(m.skipped)||0);channel.postMessage({version:1,type:'ack',token,requestId:m.requestId,ok:true});}catch(error){onError(error);channel.postMessage({version:1,type:'ack',token,requestId:m.requestId,ok:false});}};
 if(frame)source=frame;
 return {setFrame:value=>{if(!(value instanceof Blob)||value.type!=='image/png'||value.size>40000000)throw Error('Invalid frame');source=value;failed=false;send();},fail:()=>{failed=true;source=null;send();},close:()=>{closed=true;source=null;channel.close();}};
}
export function createFrameReceiver({token,onFrame,onError=()=>{},channelFactory=name=>new BroadcastChannel(name)}){
 if(!/^[a-f0-9-]{36}$/.test(token))throw Error('Invalid bridge token');const channel=channelFactory('artoftomworks.frame.'+token);let received=false,closed=false;const pending=new Map();
 channel.onmessage=async e=>{const m=e.data;if(closed||m?.version!==1||m.token!==token)return;if(m.type==='failed'){clearInterval(timer);onError(Error('Frame transfer failed. Return to the video tab and try again.'));return;}if(m.type==='ack'){const p=pending.get(m.requestId);if(p){clearTimeout(p.timer);pending.delete(m.requestId);m.ok?p.resolve():p.reject(Error('Video tab rejected the recipe'));}return;}if(received||m.type!=='frame')return;if(!(m.frame instanceof Blob)||m.frame.type!=='image/png'||m.frame.size>40000000){onError(Error('Invalid frame payload'));return;}received=true;try{await onFrame(m.frame,m.look);clearInterval(timer);}catch(error){received=false;onError(error);}};
 const hello=()=>{if(!received&&!closed)channel.postMessage({version:1,type:'hello',token});};hello();const timer=setInterval(hello,700);
 return {sendLook:(recipe,skipped=0)=>new Promise((resolve,reject)=>{if(!received||closed){reject(Error('Frame connection not ready'));return;}const requestId=globalThis.crypto.randomUUID(),timer=setTimeout(()=>{pending.delete(requestId);reject(Error('Video tab did not acknowledge the recipe'));},5000);pending.set(requestId,{resolve,reject,timer});channel.postMessage({version:1,type:'look',token,requestId,recipe,skipped});}),close:()=>{closed=true;clearInterval(timer);for(const p of pending.values()){clearTimeout(p.timer);p.reject(Error('Frame connection closed'));}pending.clear();channel.close();}};
}
